use serde_json::json;
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,io::Read,path::Path,process::{Command,Stdio}};
fn hash(p:&Path)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){assert!(src.symlink_metadata().unwrap().file_type().is_file());fs::create_dir_all(dst.parent().unwrap()).unwrap();let expected=if src.file_name().is_some_and(|n|n=="perf.data"){
 let before=fs::metadata(src).unwrap();let out=Command::new("sudo").args(["-n","sha256sum"]).arg(src).output().unwrap();assert!(out.status.success());let digest=String::from_utf8(out.stdout).unwrap().split_whitespace().next().unwrap().to_owned();let file=fs::File::create(dst).unwrap();assert!(Command::new("sudo").args(["-n","cat"]).arg(src).stdout(Stdio::from(file)).status().unwrap().success());let after=fs::metadata(src).unwrap();assert_eq!(before.len(),after.len());assert_eq!(before.modified().unwrap(),after.modified().unwrap());digest
}else{fs::copy(src,dst).unwrap();hash(src)};assert_eq!(hash(dst),expected);index.insert(dst.strip_prefix(root).unwrap().to_str().unwrap().into(),expected);}
fn tree(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){let mut paths=fs::read_dir(src).unwrap().map(|e|e.unwrap().path()).collect::<Vec<_>>();paths.sort();for p in paths{let d=dst.join(p.file_name().unwrap());if p.is_dir(){tree(&p,&d,root,index)}else if p.file_name().unwrap()!="candidate-sdk"{copy(&p,&d,root,index);}}}
fn main(){let src=Path::new("/tmp/zopro-fft-pass-grain");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-fft-pass-grain");let dst=report.join("artifacts");assert!(!dst.exists());let mut index=BTreeMap::new();for name in ["experiment.json","accepted-manifest.json","accepted-current-sha256.txt","parent-remote-head.txt","prepare.json","prepare-source-check.json","prepare-first-empty-stdout.log","native-plan.json","native.log","implement.rs","source.patch","make-protocol.rs","make-protocol.log","all-nine-template.json","perf-template.json","perf-template-with-pins.json","perf-plan.json","input-pins.json","preflight-plan.json","inventory-preflight.sh","validate-preflight.jq","preflight-validation.json","preflight-proof-inventory.json","preflight.log","perf.log","analyze.rs","analyze-tests.log","pilot-result.json","physical16-observations.json","closeout.rs","closeout.json","proof-inventory.json","followup-reading.md","publish.rs"]{copy(&src.join(name),&dst.join(name),&dst,&mut index)}for name in ["candidate","native","preflight","preflight-proofs","perf"]{tree(&src.join(name),&dst.join(name),&dst,&mut index)}let raw=index.keys().filter(|p|p.ends_with("/perf.data")).count();let symbols=index.keys().filter(|p|p.ends_with("/symbols/stdout.log")).count();assert_eq!(raw,9);assert_eq!(symbols,9);let members=index.keys().filter(|p|p.ends_with(".proof")||p.ends_with(".public")).count();assert_eq!(members,222);let sums=index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>();fs::write(dst.join("SHA256SUMS"),sums).unwrap();fs::write(dst.join("artifact-index.json"),format!("{}\n",serde_json::to_string_pretty(&json!({"files":index.len(),"proof_public_members":members,"raw_perf":raw,"expanded_symbols":symbols,"sha256":index,"scope":"Archival source/config/test/proof/measurement copies.9raw captures and9expanded streams retained locally, ignored from Git. Executables/compiler caches represented by exact build/link/source identities."})).unwrap())).unwrap();fs::write(report.join(".gitignore"),"/artifacts/**/perf.data\n/artifacts/**/symbols/stdout.log\n").unwrap();fs::write(report.join(".gitattributes"),"# Preserve the bytes of archived output and pinned source.\nartifacts/** -whitespace\n").unwrap();println!("ARCHIVE_VERIFIED {} files,222 proof/public members,9raw/9expanded retained locally",index.len());}
